Consider  the nonlinear Fokker--Planck\ equation  
\begin{equation}\label{e1.1}
\begin{array}{ll}
u_t-\Delta\beta(u)+{\rm div}(b(x,u)u)=0\mbox{ in }{\mathcal{D}}'((0,\9)\times{\mathbb{R}}^d),\vspace*{2mm}\\ 
u(0,x)=u_0(x),
\end{array}\end{equation}
where ${\beta}:{\mathbb{R}}\to{\mathbb{R}}$ and $b:{{\mathbb{R}}^d}\times{\mathbb{R}}\to{{\mathbb{R}}^d}$ satisfy  the following assumptions

The mild solution $u$ is defined~as 
$$u(t)=\lim_{h\to0}u_h(t)\mbox{ in }L^1({\mathbb{R}}^d),\ \forall t\ge0,$$where
\begin{equation}
\label{e1.6}
\begin{array}{l}
u_h(t)=u^i_h\mbox{ for }t\in[ih,(i+h)h],\ i=0,1,...,Nh=T,\vspace*{2mm}\\ 
u^{i+1}_h-h{\Delta}{\beta}(u^{i+1}_h)+h\,{\rm div}(b(x,u^{i+1}_h)u^{i+1}_h)=u^i_h\mbox{ in }{\mathcal{D}}'({\mathbb{R}}^d),\\\hfill i=0,1,...,\vspace*{2mm}\\ 
u^0_h=u_0.\end{array}	
\end{equation}

\begin{equation}
\label{e1.6}
\begin{array}{l}
u_h(t)=u^i_h\mbox{ for }t\in[ih,(i+h)h],\ i=0,1,...,Nh=T,\vspace*{2mm}\\ 
u^{i+1}_h-h{\Delta}{\beta}(u^{i+1}_h)+h\,{\rm div}(b(x,u^{i+1}_h)u^{i+1}_h)=u^i_h\mbox{ in }{\mathcal{D}}'({\mathbb{R}}^d),\\\hfill i=0,1,...,\vspace*{2mm}\\ 
u^0_h=u_0.\end{array}	
\end{equation}

The scalar product in $L^2$ is denoted $\<\cdot,\cdot\>_2$ and by ${}_{H^{-1}}\!\<\cdot,\cdot\>_{H^1}$ the pairing between $H^1$ and $H^{-1}.$ Of course, on $L^2\times L^2$ this coincides with $\<\cdot,\cdot\>_2.$ The~scalar product $\<\cdot,\cdot\>_{-1}$ on $H\1$ is  taken~as
\begin{equation}
\label{e1.8}
\<u,v\>_{-1}=\<(I-{\Delta})\1u,v\>_2,\ \forall u,v\in H\1
\end{equation}with the corresponding norm
\begin{equation}
\label{e1.9}
|u|_{-1}=(\<u,u\>_{-1})^{\frac12},\ u\in H\1.
\end{equation}

\label{t1} Let $T>0$ and let conditions {\rm(i)--(ii)} on $\beta$ and $b$ hold. For each $u_0\in L^\9\cap L^1$, the Fokker--Planck\ equation \eqref{e1.1} has at most one distributional solution 
\begin{equation}\label{add-e5}
u\in L^1((0,T);L^1)\cap L^\9((0,T)\times{{\mathbb{R}}^d}).
\end{equation}

 Let $u_1,u_2\in L^1(0,T;L^1)\cap L^\9((0,T)\times{{\mathbb{R}}^d})$ be two distributional solutions to \eqref{e1.1} and let $u=u_1-u_2.$ We have
\begin{equation}
\label{e2.1}
\begin{array}{l}
u_t-{\Delta}({\beta}(u_1)-{\beta}(u_2))+{\rm div}(b^*(x,u_1)-b^*(x,u_2))=0\\\hfill\mbox{ in }{\mathcal{D}}'((0,\9)\times{{\mathbb{R}}^d})\vspace*{2mm}\\ 
u(0,x)=0.\end{array}
\end{equation}
(Here, $b^*(x,r)=b(x,r)r,\ \forall x\in{{\mathbb{R}}^d},\ r\in{\mathbb{R}}.$)

It should be mentioned that, by (i), (ii), it follows that $u_i,\beta(u_i), b^*(\cdot, u_i)\in L^2((0,T);L^2),$ $i=1,2$, and, therefore, $u\in W^{1,2}([0,T];H^{-2}).$ 

Consider the operator $\Gamma:H\1\to H^1$ defined by
$$\Gamma u=(1-{\Delta})^{-1}u,\ u\in H\1({{\mathbb{R}}^d})$$and note that $\Gamma$ is an isomorphism of $H\1$ onto $H^1$ and $\Gamma\in L(H^{-2},L^2).$
 Since $u_i\in L^2(0,T;L^2),$ $i=1,2,$ it follows that $y=\Gamma u\in L^2(0,T;H^2)\cap W^{1,2}([0,T];L^2)$ and so, by~\eqref{e2.1},  we have
\begin{equation}
\label{e2.2}
\begin{array}{l}
\displaystyle\frac{dy}{dt}-\Gamma{\Delta}({\beta}(u_1)-{\beta}(u_2))+\Gamma\,{\rm div}(b^*(x,u_1)-b^*(x,u_2))=0,\\\hfill\mbox{ a.e. }t\in(0,T),\\
y(0)=0,\end{array}
\end{equation}
where $\frac{dy}{dt}\in L^2(0,T;L^2).$  (We note that here $\frac{dy}{dt}$ is taken in the sense of $L^2$-valued vectorial distributions on $(0,T)$ and so $y:[0,T]\to L^2$ is absolutely continuous.)

Assume first that, in addition,
\begin{equation}
\label{add-e6}
u\in L^2(0,T;H^1);\ u\in W^{1,2}([0,T];H^{-1}).
\end{equation}


Now, we take the scalar product in $L^2$ of \eqref{e2.2}  with $u=u_1-u_2$. Taking into account that
$$\<\frac{du}{dt}\,(t),u(t)\>_{-1}=\frac12\ \frac d{dt}\,|u(t)|^2_{-1}, \mbox{ a.e. }t\in(0,T),$$we get, by \eqref{e2.2} that
$$\begin{array}{l}
\displaystyle\frac 12\ \frac d{dt}\,|u(t)|^2_{-1}+\<{\beta}(u_1)-{\beta}(u_2),u_1-u_2\>_2
=\<\Gamma({\beta}(u_1)-{\beta}(u_2)),u_1-u_2\>_2\vspace*{2mm}\\ 
\qquad-\<\Gamma\,{\rm div}((b^*(x,u_1)-b^*(x,u_2)),u_1-u_2\>_2,\ \mbox{a.e. }t\in(0,T).\end{array}$$ 
By \eqref{e1.2}, this yields for a.e.~$t\in(0,T)$
\begin{equation}
 \label{e2.3}
\begin{array}{r}
\displaystyle\frac12\ \frac d{dt}\,|u(t)|^2_{-1}+{\gamma}_0|u(t)|^2_2
\le\<{\beta}(u_1(t))-{\beta}(u_2(t)),u_1(t)-u_2(t)\>_{-1}\vspace*{2mm}\\
\qquad-\<{\rm div}(b^*(x,u_1(t))-b^*(x,u_2(t))),u_1-u_2\>_{-1}.\end{array}
\end{equation}
We note that
\begin{equation}
 \label{e2.4}
 |\Gamma f|_2\le|f|_2,\ \forall f\in L^2.
\end{equation}
We also have
\begin{equation}
 \label{e2.5}
|{\rm div}\,F|_{-1}\le2|F|_2,\ \forall F\in (L^2)^d.
\end{equation}This  yields
\begin{equation}
 \label{e2.6}
 \begin{array}{ll}
|\<{\beta}(u_1)-{\beta}(u_2),u_1-u_2\>_{-1}| \le|{\beta}(u_1)-{\beta}(u_2)|_{2}|u|_{-1} 
\le{\beta}_M|u|_2|u|_{-1}
\end{array}\end{equation}and
\begin{equation}
 \label{e2.7}
\begin{array}{l}
\left|\<{\rm div}\ (b^*(x,u_1)-b^*(x,u_2)),u_1-u_2\>_{-1}\right|\vspace*{2mm}\\
\qquad\le
2|b^*(x,u_1)-b^*(x,u_2)|_2|u_1-u_2|_{-1}\vspace*{2mm}\\
\qquad\le2(|b|_\9+b_M|u_1|_\9)|u|_2|u|_{-1},
\end{array}
\end{equation}
where $M=\max\{|u_1|_\9,|u_2|_\9)$ and
$$\begin{array}{lcl}
{\beta}_M&=&\displaystyle\sup\{{\beta}'(r);\ |r|\le M\},\vspace*{2mm}\\ 
b_M&=&\displaystyle\sup\left\{\frac{|b(x,u_1)-b(x,u_2)|}{|r_1-r_2|};\ x\in{{\mathbb{R}}^d},\ |r_1|,|r_2|<M\right\}\vspace*{2mm}\\&\le&
\sup\{|b_r(x,r)|;|r|\le M,\ x\in{{\mathbb{R}}^d}\} < \infty \end{array}$$
by (ii).

By \eqref{e2.3}--\eqref{e2.7}, we get
$$\begin{array}{r}
\displaystyle\frac12\ \frac d{dt}\,|u(t)|^2_{-1}+{\gamma}_0|u(t)|^2_{2}
\le({\beta}_M+2(|b|_\9+b_M|u_1|_\9)
|u(t)|^{}_2|u(t)|^{}_{-1},\\\hfill\mbox{a.e. }t\in(0,T).\end{array}$$
This yields
$$\frac d{dt}\,|u(t)|^2_{-1}\le C|u(t)|^2_{-1},\mbox{ a.e. }t\in(0,T).$$Since $u:[0,T]\to H^{-1}$ is absolutely continuous and narrowly continuous, we infer that $|u(t)|_{-1}=0$, $\forall t\in[0,T]$, and so $u\equiv0$, as claimed.
To conclude the proof, we shall prove

 $1^\circ$. We shall first assume   that $u$ satisfies   the stronger initial condition
\begin{equation}
\label{add-e7}
\mbox{essential }\lim_{t\to0} \int_{{\mathbb{R}}^d} |u(t,x)-u_0(x)|dx=0.
\end{equation}
Next, we consider the truncated function
\begin{equation}
\label{add-e8}
\beta_M(r)=\left\{\begin{array}{ll}
\beta(r)&\mbox{ if }|r|\le M,\vspace*{2mm}\\
\beta(M)+\beta'(M)(r-M)&\mbox{ if }r>M,\vspace*{2mm}\\
\beta(-M)+\beta'(-M)(r+M)&\mbox{ if }r<-M,\end{array}\right.
\end{equation}where $M=\|u\|_{L^\9(0,T)\times{\mathbb{R}}^d)}.$

We set
$$f(t,x)\equiv b^*(x,u(t,x)),\ \ f_\nu=f*\rho_\nu,\ \ \nu>0,$$where $\rho_\nu$ is a standard mollifier on ${\mathbb{R}}^{d+1}$ and $b^*(x,u)\equiv b(x,u)u$.

We note that in equation \eqref{e1.1} one can take $\beta\equiv\beta_M$ because $|u|_\9\le M.$

We consider the equations
\begin{equation}
\label{add-e9}
\begin{array}{l}
\widetilde u_t-\Delta\beta_M(\widetilde u)+{\rm div}(f)=0\mbox{ in }(0,T)\times{\mathbb{R}}^d,\vspace*{2mm}\\
\widetilde u(0)=u_0,\end{array}\qquad
\end{equation}
\begin{equation}
\label{add-e10}
\begin{array}{l}
(\widetilde u_\nu)_t-\Delta\beta_M(\widetilde u_\nu)+{\rm div}(f_\nu)=0\mbox{ in }(0,T)\times{\mathbb{R}}^d,\vspace*{2mm}\\
\widetilde u_\nu(0)=u_0.\end{array}
\end{equation}
Clearly, \eqref{add-e9} has a unique solution $\widetilde u$ satisfying \eqref{add-e6}, i.e.,
\begin{equation}
\label{add-e11}
\widetilde u \in L^2(0,T;H^1),\ \widetilde u\in W^{1,2}([0,T];H^{-1}),
\end{equation}
while $\widetilde u_\nu$ is more regular, that is,   additionally to \eqref{add-e11} it satisfies
\begin{equation}\label{add-e12}
\widetilde u_\nu\in L^\9((0,T)\times {\mathbb{R}}^d)\cap C^1([0,T];L^1),
\end{equation}because the operator $u\to-\Delta\beta_M(u)$ is $m$-accretive in $L^1({\mathbb{R}}^d)$ and $u_0\in(L^1\cap L^\9)({\mathbb{R}}^d)$, ${\rm div}\,f_\nu\in(L^1\cap L^\9)((0,T)\times{\mathbb{R}}^d)$. 
It is also clear that
\begin{equation}
\label{add-e13}
\begin{array}{ll}
\displaystyle\lim_{\nu\to0} \widetilde u_\nu=\widetilde u
&\mbox{ strongly in }L^2(0,T;H\1).\end{array}
\end{equation}
To prove the claim, we are going to show that
\begin{equation}
\label{add-e14}
\widetilde u=u,\mbox{ a.e. in }(0,T)\times{\mathbb{R}}^d.
\end{equation}
To this end, we shall invoke an argument due to Brezis \& Crandall \cite{3}.

 Namely, we subtract equations \eqref{e1.1}, \eqref{add-e10} and get
 $$(\widetilde u_\nu- u)_t-\Delta(\beta(\widetilde u_\nu)-\beta(u)=-{\rm div}(f_\nu-f)\mbox{ in }{\mathcal{D}}'((0,T)\times{\mathbb{R}}^d),$$
 $$\mbox{essential }\lim_{t\to0}\int_{{\mathbb{R}}^d}|\widetilde u_\nu(t,x)-u(t,x)|dx=0.$$
 We set $z_\nu=\widetilde u_\nu-u$, $h_\nu=\beta(\widetilde u_\nu)-\beta(u)$ and get
 \begin{equation}
 \label{add-e14a}
 (z_\nu)_t-\Delta h_\nu=-{\rm div}(f_\nu-f)\mbox{   in }{\mathcal{D}}'((0,T)\times{\mathbb{R}}^d),
 \end{equation}
\begin{equation}
\label{add-e14'}
\mbox{essential }\lim_{t\to0}\int_{{\mathbb{R}}^d}|z_\nu(t,x)|dx=0.
\end{equation}
Arguing as in \cite{3} (proof of Proposition 1), we set
$$g^\nu_{\varepsilon}(t)=(B_{\varepsilon}(z_\nu),z_\nu),\ B_{\varepsilon}=({\varepsilon} I-\Delta)^{-1},$$where $(\ ,\ )$ denotes the inner product in $L^2=L^2({\mathbb{R}}^d)$, and get
$$(g^\nu_{\varepsilon}(t))_t=2({\varepsilon} B_{\varepsilon}(h_\nu)-h_\nu,z_\nu(t))+2(f_\nu-f,\nabla B_{\varepsilon}(z_\nu))$$and, therefore (we note that $(h_\nu,z_\nu)\ge0$),
 \begin{equation}
\label{add-e15}
g^\nu_{\varepsilon}(t)\le2\displaystyle\int^t_0{\varepsilon}(B_{\varepsilon}(h_\nu(s)),z_\nu(s))ds
+2\displaystyle\int^t_0((f_\nu-f)(s),\nabla B_{\varepsilon}(z_\nu(s)))ds,
\end{equation}because, by \eqref{add-e14'}, we have, since $z_\nu\in L^\9\cap L^1$,
 \begin{equation}
\label{add-e16}
g^\nu_{\varepsilon}(0^+)=\mbox{essential }\lim_{t\to0}(B_{\varepsilon}(z_\nu(t),z_\nu(t))=0.
\end{equation}
Recalling that, for a.e. $s\in[0,T]$,
$${\varepsilon} B_{\varepsilon}(z_\nu(s))-\Delta B_{\varepsilon}(z_\nu(s))=z_\nu(s),$$we get
$$g^\nu_{\varepsilon}(s)=(B_{\varepsilon}(z_\nu(s)),z_\nu(s))={\varepsilon}|B_{\varepsilon}(z_\nu(s))|^2_{L^2}+|\nabla B_{\varepsilon}(z_\nu(s))|^2_{L^2}$$
and so, by \eqref{add-e15}, we have
 \begin{equation}
\label{add-e17}
g^\nu_{\varepsilon}(t)\le2\displaystyle\int^t_0{\varepsilon}(B_{\varepsilon} h_\nu(s),z_\nu(s))ds
+\displaystyle\int^t_0|(f_\nu-f)(s)|^2_{L^2}ds+\displaystyle\int^t_0 g^\nu_{\varepsilon}(s)ds.
\end{equation}Hence, by Gronwall's inequality,
 \begin{equation}
\label{add-e18}
g^\nu_{\varepsilon}(t)\le\int^t_0(2{\varepsilon}(B_{\varepsilon} (h_\nu(s)),z_\nu(s))+|(f_\nu-f)(s)|^2_{L^2})e^{t-s}ds.
\end{equation}
On the other hand, by Lemma 1 in \cite{3} we have for a.e. $s\in[0,T]$ and also in $L^1(0,T)$
 \begin{equation}
\label{add-e18a}
\lim_{{\varepsilon}\to0}({\varepsilon} B_{\varepsilon} (h_\nu(s)),z_\nu(s))=0.
\end{equation}
By \eqref{add-e18}, this yields
 \begin{equation}
	\label{add-e22a}
	(G*z_\nu(t),z_\nu(t))\le\int^t_0|(f_\nu-f)(s)|^2_{L^2}e^{t-s}ds,\end{equation}
since $$\lim_{{\varepsilon}\to0}g^\nu_{\varepsilon}(t)=((-\Delta)^{-1}z_\nu(t),z_\nu(t))=(G*z_\nu(t),z_\nu(t)),$$where $G$ is the classical Newtonian Green function. We note that the  latter  inner product is well defined, since $z_\nu\in\displaystyle\bigcap_{p\in[1,\9]}L^p$ and hence $G*z_\nu\in L^{\frac{2d}{d-2}}.$ Letting $\nu\to0$ in \eqref{add-e22a}, we find
$$\lim_{\nu\to0}(G*z_\nu(t),z_\nu(t))=0.$$
In particular, $\xymatrix{z_\nu(t)\ar[r]_{\ \ \nu\to0}&0}$ in $H^{-1}$. Since $\xymatrix{z_\nu\ar[r]_{\nu\to0\ \ }&\widetilde u-u}$ in $L^2(0,T;L^2)$ by~\eqref{add-e13}, we have along a subsequence $\xymatrix{z_\nu(t)\ar[r]_{\nu\to0\ \ \ \ }&(\widetilde u-u)(t)}$ in $L^2$ for a.e. $t\in[0,T]$, hence \eqref{add-e14} follows.

\bigskip\noindent$2^\circ$. {\it The proof without assuming  \eqref{add-e7}.} It follows by the argument described under (1.12)  in \cite{3} that \eqref{e1.4} indeed implies \eqref{add-e16}. So, assumption \eqref{add-e7} can be dropped.

This completes the proof.
\hfill$\Box$

\label{p2} Assume that {\rm (i), (ii), (ii')} hold, and that, for $\Phi(u)\equiv\frac{\beta(u)}u$,
\begin{itemize}
	\item[{\rm(iii)}] $\Phi\in C^2({{\mathbb{R}}^d}).$
	\end{itemize}
	 Then, for each $u_0\in L^1\cap L^\9$, the mild solution $u$ to \eqref{e1.1} satisfies also
\begin{equation}
 \label{e2.8}
u\in L^\9((0,T)\times{{\mathbb{R}}^d}),\ \forall T>0.
\end{equation}

 We rewrite \eqref{e1.1} as
\begin{equation}
 \label{e2.9}
\begin{array}{l}
(u-|u_0|_\9-\alpha(t))_t-{\Delta}({\beta}(u)-{\beta}(|u_0|_\9+{\alpha}(t)))\vspace*{2mm}\\ \qquad
+{\rm div}(b^*(x,u)-b^*(x,|u_0|_\9+{\alpha}(t)))\vspace*{2mm}\\ 
\qquad=-{\rm div}(b^*(x,|u_0|_\9+{\alpha}(t)))-{\alpha}'(t)\le0\mbox{ in }(0,\9)\times{{\mathbb{R}}^d},
\end{array}
\end{equation}where ${\alpha}\in C^1([0,\9))$ is chosen in such a way that
\begin{equation}
\label{e2.10}
\hspace*{-3mm}\begin{array}{l}
{\alpha}'(t)+\sup\{|b_x(x,|u_0|_\9+{\alpha}(t))|;x\in{{\mathbb{R}}^d}\}(|u_0|_\9+{\alpha}(t))=0,\   t\in(0,T),\vspace*{2mm}\\ 
{\alpha}(0)=0.\end{array}
\end{equation}
We may find ${\alpha}$ of the form ${\alpha}=\eta-|u_0|_\9,$ where $\eta$ is a solution to the equation 
\begin{equation}
\label{e2.11}
\begin{array}{l}
\eta'-\delta(\eta)\eta  =0,\ t\ge0,\vspace*{2mm}\\ 
\eta(0)=|u_0|_\9,\end{array}
\end{equation} $\delta(r)=\sup\{|b_x(x,r)|;x\in{{\mathbb{R}}^d}\},$ $r\in{\mathbb{R}}.$ Clearly, \eqref{e2.11} has such a solution    $\eta\in C^1([0,\9)),$ $\eta\ge0,$ on $[0,\9)$ because $\delta\in C_b({\mathbb{R}}).$ 


Formally, if we multiply \eqref{e2.9} by ${\rm sign}(u-|u_0|_\9-{\alpha})^+$,   integrate over ${{\mathbb{R}}^d}$  and use the monotonicity of ${\beta}$, we get by \eqref{e2.5} that  
\begin{equation}\label{e2.11a}
	\frac d{dt}\,|(u(t)-|u_0|_\9-{\alpha}(t))^+|_1\le0,\ \mbox{a.e. }t\in(0,T). \end{equation}This yields $u(t)\le|u_0|_\9+{\alpha}(t)$, $\forall t\ge0$, and similarly it follows that $u(t)\ge-|u_0|_\9-{\alpha}(t).$ Hence, $u\in L^\9((0,T)\times{{\mathbb{R}}^d}),$ as claimed.

The above formal argument can be made rigorous if $u$ is a strong solution to \eqref{e1.1} (which is not the case here). Then (see the detailed argument in \cite{1})
\begin{equation}\label{e2.11aa}
\hspace*{-2mm}\begin{array}{l}
\displaystyle\lim_{\delta\to0}\frac1\delta
\int_{[0<(\beta(u)-\beta(|u_0|_\9+{\alpha}(t))^+)\le\delta]}
|b^*(x,u)-b^*(x,|u_0|_\9+{\alpha}(t))|\,|\nabla u|dx\vspace*{2mm}\\
\qquad=\displaystyle\lim_{\delta\to0}\frac1\delta
\int_{[0<(\beta(u)-\beta(|u_0|_\9+{\alpha}(t))^+)\le\delta]}
(|b(x,u)-b(x,|u_0|_\9+{\alpha}(t))|\,|u|
\vspace*{2mm}\\\qquad+|b(x,|u_0|_\9+{\alpha}(t))|\,|u-|u_0|_\9-{\alpha}(t)|)|\nabla u|dx=0,\ \forall t\in(0,T),\end{array}\end{equation}which is true if $\nabla u\in L^2(0,T;L^2)$ and $b(x,\cdot)\in{\rm Lip}({\mathbb{R}})$ uniformly in $x$ (which is the case if $b_u\in C_b({{\mathbb{R}}^d}\times{\mathbb{R}}))$. In order to be in  such a situation, we approximate \eqref{e1.1}~by
\begin{equation}\label{e2.11aaa}
\begin{array}{l}
u_t-{\Delta}({\beta}(u)+{\varepsilon}{\beta}(u)+{\rm div}(b_{\varepsilon}(x,u)u))=0\mbox{ in }(0,T)\times{{\mathbb{R}}^d},\vspace*{2mm}\\
u(0,x)=u_0(x),\end{array}\end{equation}where ${\varepsilon}>0$ and $b_{\varepsilon}\in C^1_b({{\mathbb{R}}^d}\times{\mathbb{R}})$ is a smooth approximation of $b$. (For instance, $b_{\varepsilon}=b*\rho_{\varepsilon}$, where $\rho_{\varepsilon}$ is a standard mollifier.) Then, as proved earlier in \cite{1}, \cite{2az}, \cite{2}, equation \eqref{e2.11aaa} has a unique solution $u_{\varepsilon}\in L^2(0,T;H^1)\cap C([0,T];L^1)\cap W^{1,2}([0,T];H\1)$ and $u_{\varepsilon}\to u$ in $C([0,T];L^1)$ as ${\varepsilon}\to0$. An easy way to prove this is to apply the Trotter--Kato theorem to the family of $m$-accretive operators in $L^1$
$$\begin{array}{lcl}
A_{\varepsilon} u&=&-{\Delta}{\beta}(u)+{\varepsilon}{\beta}(u)+{\rm div}(b_{\varepsilon}(x,u)u),\vspace*{2mm}\\ 
D(A_{\varepsilon})&=&\{u\in L^1;-\Delta\beta(u)+{\varepsilon}\beta(u)+{\rm div}(b_{\varepsilon}(x,u)u)\in L^1\}.\end{array}$$
(See the argument in \cite{2}.) Then, we replace \eqref{e2.9} by
\begin{equation}\label{e2.14a}
\begin{array}{l}
(u_{\varepsilon}-|u_0|_\9-{\alpha}(t))_t-{\Delta}({\beta}(u_{\varepsilon})-{\beta}(|u_0|_\9+{\alpha}(t)))\vspace*{2mm}\\
+{\varepsilon}({\beta}(u)-{\beta}(|u_0|_\9+{\alpha}(t)))+{\rm div}(b^*_{\varepsilon}(x,u_{\varepsilon})-b^*_{\varepsilon}(x,|u_0|_\9+{\alpha}(t))\vspace*{2mm}\\
=-b^*_{\varepsilon}(x,|u_0|_\9+{\alpha}(t))-{\alpha}'(t)-{\varepsilon}\beta(|u_0|_\9+{\alpha}(t))\le0,\vspace*{2mm}\\\hfill \mbox{ a.e. in }(0,T)\times{{\mathbb{R}}^d},\end{array}\end{equation}
where $b^*_{\varepsilon}(u)=b_{\varepsilon}(u)u.$

Let ${\mathcal{X}}_\delta\in{\rm Lip}({\mathbb{R}})$ be the following approximation of the signum function
$${\mathcal{X}}_\delta(r)=\left\{\begin{array}{rll}
1&\mbox{for }&r\ge\delta,\vspace*{2mm}\\ 
\displaystyle\frac r\delta&\mbox{for }&|r|<\delta,\vspace*{2mm}\\ 
-1&\mbox{for }r<-\delta,\end{array}\right.$$where $\delta>0.$ If we multiply \eqref{e2.14a} by ${\mathcal{X}}_\delta((\beta(u_{\varepsilon})-\beta(|u_0|_\9+{\alpha}))^+)$ and integrate over ${{\mathbb{R}}^d}$, we get
$$\!\!\!\begin{array}{l}
\displaystyle\int_{{{\mathbb{R}}^d}}(u_{\varepsilon}-|u_0|_\9-{\alpha})_t{\mathcal{X}}_\delta((\beta(u_{\varepsilon})-\beta(|u_0|_\9+{\alpha}))^+)dx\\ 
\qquad\le\displaystyle\frac1\delta
\int_{[0<(\beta(u_{\varepsilon})-\beta(|u_0|_\9+{\alpha}))^+\le\delta]}
(b^*(x,u_{\varepsilon})u_{\varepsilon}-b^*_{\varepsilon}(x,|u_0|_\9+{\alpha}))\cdot\nabla u_{\varepsilon}\,dx,\\\hfill \forall t\in(0,T),\end{array}$$because $\beta$ is monotonically increasing and 
$$\begin{array}{r}
\displaystyle\nabla(\beta(u_{\varepsilon})-\beta(|u_0|_\9+{\alpha})\cdot\nabla{\mathcal{X}}_\delta
((\beta(u_{\varepsilon})-\beta(|u_0|_\9+{\alpha}))^+)\ge0\mbox{ in } (0,T)\times{{\mathbb{R}}^d}.\end{array}$$
